function metricGridHTML(tiles) {
  if (!tiles.length) return "";
  const cols = tiles.length === 1 ? 'cols-1' : tiles.length === 3 ? 'cols-3' : '';
  return `
    <div class="kpi-grid ${cols}">
      ${tiles.map(t => `
        <div class="kpi-tile">
          <div class="value">${escText(t.value || "")}</div>
          <div class="label">${escText(t.label || "")}</div>
          ${t.delta ? `<div class="delta ${t.direction || 'up'}">${escText(t.delta)}</div>` : ""}
        </div>`).join("")}
    </div>`;
}

function newsItemHTML(it) {
  const photos = it.photos || [];
  const ratio = it.photoRatio || '4/3';
  const textBlock = `
    ${it.title ? `<h4>${escText(it.title)}</h4>` : ""}
    ${it.text  ? `<p>${escText(it.text).replace(/\n/g, '<br>')}</p>`   : ""}`;
  if (photos.length && it.photoLayout === 'side') {
    return `
      <div class="news-with-photo">
        <div>${textBlock}</div>
        <div class="photo-side" style="background-image:url('${photos[0]}')"></div>
      </div>`;
  }
  const photoGrid = photos.length ? `
    <div class="pt-photos n${Math.min(photos.length, 4)}">
      ${photos.slice(0, 4).map(p => `<div class="pt-img" style="background-image:url('${p}');aspect-ratio:${ratio}"></div>`).join("")}
    </div>` : "";
  return `
    <div class="news-block">
      <div class="ach-item">
        <div class="ach-content">${textBlock}</div>
      </div>${photoGrid}
    </div>`;
}

function pageBlock(compKey, block) {
  const meta      = getCompMeta(compKey);
  const label     = getBlockLabel(block.type);
  const shortName = meta.name.split("(")[0].trim();
  const itemsHTML = block.items.map(it => {
    if (it.kind === 'metric') {
      const tiles = it.tiles && it.tiles.length ? it.tiles
        : [{ value: it.value||'', label: it.label||'', delta: it.delta||'', direction: it.direction||'up' }];
      return metricGridHTML(tiles);
    }
    return `<div class="news-block">${newsItemHTML(it)}</div>`;
  }).join('');

  const footer = block.comment ? `<div class="footer-note">ⓘ ${escText(block.comment)}</div>` : "";
  return `
    <div class="page content theme-${meta.theme}">
      <div class="header">
        <h2>${escText(label)}</h2>
        <img src="logos/logo-${meta.key}.svg" class="company-logo" alt="${escAttr(meta.name)}">
      </div>
      <div class="ach-items">${itemsHTML}</div>
      ${footer}
    </div>`;
}

function renderPreview() {
  const pv = document.getElementById("preview");
  if (!pv) return;
  const hasContent = state.companies.some(c => c.blocks.length > 0);
  if (!hasContent) {
    pv.innerHTML = `<div class="empty-state"><img src="logos/kao.svg" class="empty-kao"><div>здесь пока пусто</div></div>`;
    return;
  }
  let html = pageCover() + pageLetter();
  for (const comp of state.companies) {
    if (!comp.blocks.length) continue;
    html += pageCompanyDivider(comp.key);
    for (const block of comp.blocks) html += pageBlock(comp.key, block);
  }
  pv.innerHTML = html;
}

function renderAccountBar() {
  const el = document.getElementById("accountBar");
  if (!el) return;

  if (!currentUser) {
    el.innerHTML = `
      <div class="account-row auth-row">
        <input id="authEmail" type="email" placeholder="email">
        <input id="authName" type="text" placeholder="name">
        <input id="authPassword" type="password" placeholder="password">
        <button type="button" onclick="loginAccount()">Login</button>
        <button type="button" onclick="registerAccount()">Register</button>
      </div>
      <div class="account-status">Local draft mode. JSON export includes images.</div>`;
    return;
  }

  const digestOptions = remoteDigests.length
    ? remoteDigests.map(d => `<option value="${escAttr(d.id)}" ${d.id === currentDigestId ? "selected" : ""}>${escText(d.title || "Digest")} · v${d.currentVersion || 1}</option>`).join("")
    : `<option value="">No digests</option>`;
  const revisionOptions = remoteRevisions.length
    ? remoteRevisions.map(r => {
        const date = r.createdAt ? new Date(r.createdAt).toLocaleString() : "";
        return `<option value="${escAttr(r.id)}">v${r.version} · ${escText(r.action || "autosave")} · ${escText(date)}</option>`;
      }).join("")
    : `<option value="">No versions</option>`;

  el.innerHTML = `
    <div class="account-row">
      <span class="account-user">${escText(currentUser.email || "")}</span>
      <select id="digestSelect" onchange="loadSelectedDigest()">${digestOptions}</select>
      <button type="button" onclick="newRemoteDigest()">New</button>
      <button type="button" onclick="saveRemoteNow()">Save</button>
      <button type="button" onclick="undoAction()" ${localHistory.length <= 1 ? "disabled" : ""}>Undo</button>
      <button type="button" onclick="redoAction()" ${redoHistory.length ? "" : "disabled"}>Redo</button>
      <button type="button" onclick="logoutAccount()">Logout</button>
    </div>
    <div class="account-row">
      <select id="revisionSelect">${revisionOptions}</select>
      <button type="button" onclick="rollbackRemoteRevision()" ${remoteRevisions.length ? "" : "disabled"}>Rollback</button>
      <span class="account-status">${escText(saveStatus || "Ready")}</span>
    </div>`;
}

