// ============================================================
//   PERSIST / EXPORT
// ============================================================
function exportJSON() {
  const blob = new Blob([JSON.stringify(stateEnvelope(), null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = 'digest' + '.json';
  a.click();
}
function importJSON() { document.getElementById("fileInput").click(); }
document.getElementById("fileInput").addEventListener("change", async (e) => {
  const file = e.target.files[0];
  e.target.value = '';
  if (!file) return;
  try {
    const data = JSON.parse(await file.text());
    loadState(importedState(data));
    render();
    alert("Файл загружен успешно.");
  } catch(err) {
    alert("Не удалось прочитать файл: " + (err.message || err));
  }
});

function exportPDF() {
  if (!state.companies.some(c => c.blocks.length)) { alert("Сначала добавь хотя бы один блок."); return; }

  // Named @page per element — each page sized exactly to its content height
  const pages = Array.from(document.querySelectorAll('#preview .page'));
  let css = '';
  pages.forEach((p, i) => {
    const name = `pg${i}`;
    const h = Math.ceil(p.offsetHeight);
    p.setAttribute('data-pgname', name);
    css += `@page ${name} { size: 1180px ${h}px; margin: 0; }\n`;
    css += `[data-pgname="${name}"] { page: ${name}; height: ${h}px !important; }\n`;
  });

  const sizeStyle = document.createElement('style');
  sizeStyle.id = '__print_size';
  sizeStyle.textContent = css;
  document.head.appendChild(sizeStyle);

  const tip = document.createElement('div');
  tip.className = 'print-tip';
  tip.innerHTML = `
    <div class="print-tip-box">
      <div class="print-tip-title">Сохранение в PDF</div>
      <ol class="print-tip-steps">
        <li>Принтер → <b>«Сохранить как PDF»</b></li>
        <li>Поля → <b>«Нет»</b></li>
        <li>Нажми <b>«Сохранить»</b></li>
      </ol>
      <div class="print-tip-sub">Фоновая графика включится автоматически</div>
    </div>`;
  document.body.appendChild(tip);

  setTimeout(() => {
    window.print();
    setTimeout(() => {
      if (tip.parentNode) tip.parentNode.removeChild(tip);
      const s = document.getElementById('__print_size');
      if (s) s.parentNode.removeChild(s);
      pages.forEach(p => p.removeAttribute('data-pgname'));
    }, 500);
  }, 400);
}


async function pageToDataUrl(page, scale) {
  const w = page.offsetWidth;
  const h = page.scrollHeight;

  const clone = page.cloneNode(true);
  clone.style.cssText = `position:fixed;top:-99999px;left:0;width:${w}px;margin:0;box-sizing:border-box;`;

  Array.from(clone.querySelectorAll('img')).forEach(img => {
    const src = img.getAttribute('src') || '';
    const m = src.match(/logo-([^/\\]+?)\.svg/);
    if (m && LOGO_DATA[m[1]]) img.setAttribute('src', LOGO_DATA[m[1]]);
  });

  document.body.appendChild(clone);

  await Promise.all(Array.from(clone.querySelectorAll('img')).map(img =>
    new Promise(res => { if (img.complete) res(); else { img.onload = res; img.onerror = res; } })
  ));

  try {
    const canvas = await html2canvas(clone, {
      scale,
      useCORS: false,
      backgroundColor: null,
      logging: false,
      width: w,
      height: h
    });
    return canvas.toDataURL('image/png');
  } finally {
    document.body.removeChild(clone);
  }
}

async function exportPNG() {
  if (!state.companies.some(c => c.blocks.length)) { alert("Сначала добавь хотя бы один блок."); return; }
  const pages = Array.from(document.querySelectorAll('#preview .page'));
  if (!pages.length) return;

  const btn = document.querySelector('button[onclick="exportPNG()"]');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Генерация...'; }

  try {
    const zip = new JSZip();
    for (let i = 0; i < pages.length; i++) {
      if (btn) btn.textContent = `⏳ ${i + 1} / ${pages.length}`;
      const dataUrl = await pageToDataUrl(pages[i], 3);
      zip.file(`page-${String(i + 1).padStart(2, '0')}.png`, dataUrl.split(',')[1], { base64: true });
    }
    const blob = await zip.generateAsync({ type: 'blob' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'digest' + '-pages.zip';
    a.click();
  } catch(e) {
    console.error('PNG export error:', e);
    alert('Ошибка при генерации PNG. Проверь консоль.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '🖼 Скачать PNG'; }
  }
}

function clearAll() {
  if (!confirm("Сбросить все данные?")) return;
  state.companies.forEach(c => { c.blocks = []; c.collapsed = true; });
  render();
}

// ============================================================
//   RESIZE HANDLE
// ============================================================
(function() {
  const handle = document.getElementById('resizeHandle');
  const app    = document.querySelector('.app');
  let dragging = false;

  handle.addEventListener('mousedown', () => {
    dragging = true;
    handle.classList.add('dragging');
    document.body.style.cursor     = 'col-resize';
    document.body.style.userSelect = 'none';
  });
  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    const w = Math.min(Math.max(e.clientX, 520), window.innerWidth - 400);
    app.style.setProperty('--editor-w', w + 'px');
  });
  document.addEventListener('mouseup', () => {
    if (!dragging) return;
    dragging = false;
    handle.classList.remove('dragging');
    document.body.style.cursor     = '';
    document.body.style.userSelect = '';
  });
})();

